// Motor de selección COMPLETO — TOPE-2 (validado vs GHL real 2026-09-07)
const T='ez934lu03v7nC4ZRS7LJ', E='Omg1BvHmpXR0MMGsrpFh', L='rHzGNiesWuESPmSZyviJ', UAF='jrdfZCF6VWAA3L7WDVdB';
const BOOKED_STAGE_IDS = ["36fa419c-e836-48a8-8a77-72b38d357173", "7c0c40b6-4a25-4d1c-a2a2-40e5f38095bc", "08f742d9-2aaa-4a76-abc2-48d34a9f3ba9"];
const RECENCIA_DIAS = 30;              // ⚠ null en históricos → no filtra (ver gap en la guía)
const TERMINAL = ['Cita confirmada'];
const flat = (n, key) => { try { return $(n).all().flatMap(i => (i.json && i.json[key]) || []); } catch(e){ return []; } };
const cfv = (c, id) => { for (const x of (c.customFields||[])) if (x.id===id) return x.value; return null; };
const truthy = v => v===true||v==='true'||(Array.isArray(v)&&v.includes('true'));
const now = Date.now();
// 1) contactIds con cita (opps OP·Bot en etapas booked)
const bookedOpps = flat('Query booked (OP·Bot)', 'opportunities');
const booked = new Set(bookedOpps.filter(o => BOOKED_STAGE_IDS.includes(o.pipelineStageId)).map(o => o.contactId));
const gate = (c) => {
  if (booked.has(c.id)) return false;
  let toq = cfv(c, T); toq = (toq===null||toq===''||(Array.isArray(toq)&&!toq.length))?0:Number(toq);
  if (toq >= 2) return false;                       // TOPE GLOBAL 2
  const est = (cfv(c, E)||'').toString().trim();
  if (TERMINAL.includes(est)) return false;
  const ua = cfv(c, UAF); const t = ua ? Date.parse(ua) : null;
  if (t && (now - t) > RECENCIA_DIAS*864e5) return false;
  return true;
};
const sel = new Map();
// prioridad: rescate primero (link_enviado=true, sin cita)
for (const c of flat('Query rescate','contacts')) { if (gate(c)) sel.set(c.id, {contactId:c.id, phone:c.phone, firstName:c.firstName, lane:'rescate', toques_actual: Number(cfv(c,T))||0}); }
// nurturing: estado activo SIN link (los con link ya están en rescate)
for (const c of flat('Query nurturing','contacts')) { if (sel.has(c.id)) continue; if (truthy(cfv(c,L))) continue; if (gate(c)) sel.set(c.id, {contactId:c.id, phone:c.phone, firstName:c.firstName, lane:'nurturing', toques_actual: Number(cfv(c,T))||0}); }
return [...sel.values()].map(json => ({ json }));  // 1 item/contacto; 1 msg/contacto/run
